var i=`0233-tiropita`;var n=`world-0233`;var a=`GR`;var o=`southern-europe`;var r=8;var s=51;var l={en:`Tiropita`,ua:`Тиропіта`};var g={en:`A traditional Greece dish made with feta, ricotta, chicken egg, phyllo pastry. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Греція. Основні інгредієнти: фета, рикота, куряче яйце, тісто філо. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var h=[{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:4,i:[[`feta`,350,`g`],[`ricotta`,180,`g`],[`chicken-egg`,2,`pcs`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:15,i:[[`phyllo-pastry`,300,`g`],[`unsalted-butter`,100,`g`]]},{en:`Bake in a preheated 180°C oven for about 32 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 32 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:32,i:[]}];var p={slug:i,id:n,country:`GR`,region:o,servings:8,minutes:51,title:l,text:g,steps:h};export{a as country,p as default,n as id,s as minutes,o as region,r as servings,i as slug,h as steps,g as text,l as title};